import json
from pathlib import Path
here=Path(__file__).resolve().parent

def evaluate(probe, gis):
    criteria=[
      {'criterion':'Correct identity and source-backed footprint','score':2.0,'max_score':2.0,'evidence':f"GIS FID 774 names Pi Beta Phi at 1012 State St; chapter sources support Indiana Delta identity. Fresh-open shell vs GIS: IoU {gis['iou']:.10f}, symmetric Hausdorff {gis['symmetric_hausdorff_m']:.9f} m.",'findings':'FID 841 is a distinct smaller mapped feature, explicitly excluded; its relationship remains unresolved.'},
      {'criterion':'Position, orientation, and scale/dimensions','score':1.8,'max_score':2.0,'evidence':'The GIS-derived local shell matches the source ring; the asset origin is based on the source feature center and its local bounds have plausible scale.','findings':'The local-coordinate asset has not yet been checked through the master Placement marker.'},
      {'criterion':'Evidence-backed height, floors, and roof form','score':1.3,'max_score':2.0,'evidence':'Two primary facade levels, small upper openings, continuous white parapet/cornice and screened flat roof are represented; total bounds height is 8.66 m.','findings':'Exact floor heights, foundation datum, roof height/construction are unsupported; the roof/attic and three interior floor plates are estimates.'},
      {'criterion':'Facade, entrances, and distinctive architecture','score':1.7,'max_score':2.0,'evidence':'Inspected renders show red brick, regular sash windows, white classical portico/columns, curved balcony rail, double doors/transom, address number and stairs.','findings':'Rear/side roof and terrace-like surfaces are simplified; facade details are not dimensioned; Greek-letter sign is small and low contrast.'},
      {'criterion':'Modular export, portability, and complete evidence','score':1.7,'max_score':2.0,'evidence':f"Fresh-open Blender {probe['blender_version']} confirmed expected scene/collection, 698 objects, 696 meshes, eight material families, no links or external image dependencies; evidence and renders are present.",'findings':'Shared manifest conversion and master placement marker still need root integration and fresh-open validation.'}
    ]
    score=round(sum(c['score'] for c in criteria),2)
    findings=['Passes the 8/10 building-candidate threshold.','Roof/story height and room plan remain estimates or conceptual interpretation.','Root must integrate through Placement_massing_house_301838781_891384f and verify campus-world placement.','Do not merge the separate FID 841 polygon without confirming its identity.']
    return {'building':'Pi Beta Phi / Indiana Delta chapter house','asset':probe['path'],'stable_id':'massing_house_301838781_891384f','grade':'R1','independent_review':True,'score':score,'max_score':10,'pass':score>=8,'threshold':8.0,'sha256':probe['sha256'],'expected_sha256':probe['expected_sha256'],'sha_match':probe['sha_match'],'criteria':criteria,'evidence':{'fresh_open':{'blender_version':probe['blender_version'],'scene':probe['scene'],'collection_present':probe['collection_present'],'object_count':probe['object_count'],'mesh_count':probe['mesh_count'],'bounds_local_m':probe['bounds_local_m'],'material_count':probe['material_count'],'linked_libraries':probe['linked_libraries'],'external_file_images':probe['external_file_images']},'independent_gis_comparison':gis,'source_register':'audit/pi_beta_phi/source_register.md','render_review':['audit/pi_beta_phi/view_front.png','audit/pi_beta_phi/view_three_quarter.png','audit/pi_beta_phi/view_interior_cutaway.png'],'visual_review':'Front and three-quarter renders show a coherent GIS-shaped brick shell with a modeled entry. Interior cutaway shows floor plates, partitions and use cues, but is schematic.'},'findings':findings,'grader_notes':'Independent review of the asset itself; pending master placement integration is deducted rather than presumed complete.'}

probe=json.loads((here/'fresh_open_probe.json').read_text())
gis=json.loads((here/'gis_comparison.json').read_text())
result=evaluate(probe,gis)
(here/'result.json').write_text(json.dumps(result,indent=2))
md=['# Independent Pi Beta Phi Grade R1','',f"Result: {result['score']:.1f}/10 - {'PASS' if result['pass'] else 'FAIL'} (threshold: 8.0/10)",'',f"Frozen asset SHA-256: `{probe['sha256']}`",'',f"Fresh open: Blender {probe['blender_version']}; scene `{probe['scene']}`; {probe['object_count']} objects; {probe['mesh_count']} meshes; {probe['material_count']} material families; no linked libraries or file-backed images.",'',f"Independent GIS comparison: IoU {gis['iou']:.10f}, symmetric Hausdorff {gis['symmetric_hausdorff_m']:.9f} m, centroid delta {gis['centroid_delta_m']} m.",'','| Criterion | Score | Evidence and finding |','| --- | ---: | --- |']
for c in result['criteria']:
    md.append(f"| {c['criterion']} | {c['score']:.1f}/{c['max_score']:.1f} | {c['evidence']} {c['findings']} |")
md += ['', '## Findings','']+[f"- {x}" for x in result['findings']]+['','## Visual review','','The front and three-quarter renders show a coherent brick facade, regular windows, white portico and columns, curved entry rail, doors, address and stairs. The interior cutaway includes floor plates, partitions and room-use cues, but is schematic rather than a verified plan. Flat roof, parapet, facade dimensions and exact vertical arrangement remain estimates.','', 'The local asset opens and is self-contained. Master placement through the expected Placement marker remains pending root integration.']
(here/'grade_report.md').write_text('\n'.join(md)+'\n',encoding='utf-8')
print(json.dumps({'score':result['score'],'max_score':result['max_score'],'pass':result['pass']}))
